
create table if not exists public.financial_budget_plan_ownership(plan_id uuid primary key references public.budget_plans(id),organization_id uuid not null references public.organizations(id),entity_id uuid,cost_center_id uuid,fiscal_start date not null,adopted_by uuid not null references auth.users(id),created_at timestamptz not null default now(),legacy_snapshot jsonb not null default '{}',unique(plan_id,organization_id));
create table if not exists public.financial_budget_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null,plan_id uuid not null,budget_line_id uuid not null references public.budget_lines(id),classification_id uuid not null,entity_id uuid,cost_center_id uuid,metric_policy text not null,effective_from date not null,effective_to date not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(plan_id,organization_id) references public.financial_budget_plan_ownership(plan_id,organization_id),foreign key(classification_id,organization_id) references public.financial_classifications(id,organization_id),check(effective_to>=effective_from));
create table if not exists public.financial_budget_event_routes(event_id uuid primary key,organization_id uuid not null,entity_id uuid not null,cost_center_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(event_id,organization_id) references public.financial_events(id,organization_id));
create table if not exists public.financial_budget_scope_grants(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),user_id uuid not null references auth.users(id),entity_id uuid,cost_center_id uuid,can_edit boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.financial_budget_commands(organization_id uuid not null references public.organizations(id),source_key text not null,canonical_payload jsonb not null,payload_hash text not null,result_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),primary key(organization_id,source_key));
create table if not exists public.financial_budget_commitment_consumptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,commitment_line_id uuid not null,actual_line_id uuid not null,base_amount numeric(24,4) not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(base_amount>0),check(commitment_line_id<>actual_line_id));
create table if not exists public.financial_budget_retirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),grant_id uuid unique,mapping_id uuid unique,reason text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(num_nonnulls(grant_id,mapping_id)=1));
do $$declare t text;begin foreach t in array array['financial_budget_plan_ownership','financial_budget_mappings','financial_budget_event_routes','financial_budget_scope_grants','financial_budget_commands','financial_budget_commitment_consumptions','financial_budget_retirements'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy fc_budget_member_read on public.%I for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=%I.organization_id and m.user_id=auth.uid() and m.status=''ACTIVE''))',t,t);end loop;end$$;
grant select on public.financial_budget_plan_ownership,public.financial_budget_mappings,public.financial_budget_event_routes,public.financial_budget_scope_grants,public.financial_budget_commands,public.financial_budget_commitment_consumptions,public.financial_budget_retirements to authenticated;
